using System;using System.Linq;using System.Xml.Linq;
class Program{
 static int checks;static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;}
 static ItemStack Stack(int count)=>new ItemStack(new ItemValue{type=7,Data="exact-source-seed-meta-mod-texture-double"},count);
 static XElement Cells(string name,params ItemStack[] stacks)=>new XElement(name,stacks.Select(s=>new XElement("slot",new XAttribute("count",s.count),new XAttribute("data",RebirthNativeItemCodec.Encode(s.itemValue)))));
 static XElement Payment(){RebirthStationGridSnapshotCodec.TryWrite(new[]{ItemStack.Empty},out var input);return new XElement("playerPayment",new XAttribute("version",1),new XAttribute("source","ownerInventory"),new XAttribute("ownerKey","owner-A"),new XAttribute("ownerId","native-owner-A"),new XAttribute("ownedBelt",1),Cells("bagBefore",Stack(3),Stack(5)),Cells("bagAfter",ItemStack.Empty,Stack(4)),Cells("beltBefore",Stack(2)),Cells("beltAfter",Stack(2)),new XElement("bagLocks",new XAttribute("data","00")),new XElement("beltLocks",new XAttribute("data","null")),new XElement("allocations",new XElement("take",new XAttribute("source","bag"),new XAttribute("slot",0),new XAttribute("count",3)),new XElement("take",new XAttribute("source","bag"),new XAttribute("slot",1),new XAttribute("count",1))),new XElement("stationInput",input));}
 static XElement Admission(XElement payment,string job=null,string address="vehicle-A/station-A"){
 job??=Guid.NewGuid().ToString("N");string creation=Guid.NewGuid().ToString("N");RebirthStationGridSnapshotCodec.TryWrite(new[]{Stack(3),Stack(1)},out var paid);paid.Name="paid";
 var parent=new XElement("stationAdmission",new XAttribute("version",8),new XAttribute("job",job),new XAttribute("creation",creation),new XAttribute("definition","recipe-current"),new XAttribute("x",0),new XAttribute("y",0),new XAttribute("z",0),new XAttribute("block","actual-window-policy-double"),new XAttribute("stationAddress",address),paid);
 var wrapper=new XElement("stationAdmission",parent.Attributes().Select(a=>new XAttribute(a)));wrapper.SetAttributeValue("version",12);wrapper.Add(new XAttribute("paymentSource","ownerInventory"),new XElement("parentAdmission",parent),new XElement(payment));return wrapper;}
 static void Main(){
 var p=Payment();Check(RebirthCamperStationPlayerPaymentImage.TryRead(p,out var image),"actual image read");Check(XNode.DeepEquals(p,image.Write()),"immutable roundtrip");
 image.CopyImages(out var before,out var after,out var beltBefore,out var beltAfter);Check(image.MatchesBefore(before,beltBefore,new[]{false,false},null,1),"full original source witness");Check(image.MatchesAfter(after,beltAfter),"complete exact after witness");before[0].itemValue.Data+="drift";Check(!image.MatchesBeforeSlots(before,beltBefore),"changed native payload refuses");Check(image.MatchesAfter(after,beltAfter),"returned clone cannot mutate retained image");
 foreach(string mutation in new[]{"count","source","allocation","comment","locks"}){var bad=Payment();if(mutation=="count")bad.Element("bagAfter").Elements().Last().SetAttributeValue("count",5);if(mutation=="source")bad.SetAttributeValue("source","stationInput");if(mutation=="allocation")bad.Element("allocations").Elements().First().SetAttributeValue("slot",99);if(mutation=="comment")bad.Add(new XComment("unexpected"));if(mutation=="locks")bad.Element("bagLocks").SetAttributeValue("data","0");Check(!RebirthCamperStationPlayerPaymentImage.TryRead(bad,out _),"malformed image "+mutation);}
 var root=Admission(Payment());Check(RebirthStationGridAdmission.TryReadStored(root,out var prepared),"actual actor parser12");Check(prepared.TryMarkPublicationAttempted(out var attempted),"actual12->13");Check(!attempted.TryMarkPublicationAttempted(out _),"duplicate attempt refused");Check(attempted.TryConfirmPlayerPayment(out var confirmed),"actual13->14");Check(!confirmed.TryConfirmPlayerPayment(out _),"duplicate confirmation refused");Check(RebirthCamperStationPlayerPayment.Operation(attempted)==RebirthCamperStationPlayerPayment.Operation(confirmed),"operation stable after saved confirmation");
 Check(RebirthStationOfflineClaims.Compatible("owner-A",attempted,"owner-A",prepared),"forward12->13 compatible");Check(RebirthStationOfflineClaims.Compatible("owner-A",confirmed,"owner-A",attempted),"forward13->14 compatible");Check(!RebirthStationOfflineClaims.Compatible("owner-A",prepared,"owner-A",attempted),"reverse13->12 refused");Check(!RebirthStationOfflineClaims.Compatible("owner-A",attempted,"owner-A",confirmed),"reverse14->13 refused");Check(!RebirthStationOfflineClaims.Compatible("owner-B",confirmed,"owner-A",attempted),"changed journal owner refused");
 foreach(string mutation in new[]{"job","owner","operation","source","extra"}){var bad=confirmed.Write();if(mutation=="job")bad.SetAttributeValue("job",Guid.NewGuid().ToString("N"));if(mutation=="owner")bad.Element("ownerPaymentConfirmed").SetAttributeValue("ownerId","other");if(mutation=="operation")bad.Element("ownerPaymentConfirmed").SetAttributeValue("operation",Guid.NewGuid().ToString("N"));if(mutation=="source")bad.Element("playerPayment").Element("bagBefore").Elements().Last().SetAttributeValue("data",RebirthNativeItemCodec.Encode(new ItemValue{type=7,Data="other"}));if(mutation=="extra")bad.Add(new XElement("surprise"));Check(!RebirthStationGridAdmission.TryReadStored(bad,out _),"confirmed binding tamper "+mutation);}
 var otherRoot=Admission(Payment(),address:"vehicle-B/station-B");Check(RebirthStationGridAdmission.TryReadStored(otherRoot,out var other),"second station source");Check(!RebirthStationOfflineClaims.Compatible("owner-A",prepared,"owner-A",other),"same owner bag collision across installations");
 var identity=new RebirthStablePlayerIdentity{StorageKey="owner-A",CanonicalId="native-owner-A"};var operation=RebirthCamperStationPlayerPayment.Operation(attempted);
 var envelope=new XElement("camperPlayerDebit",new XAttribute("version",1),new XAttribute("actor",17),new XAttribute("owner",identity.StorageKey),new XAttribute("canonical",identity.CanonicalId),attempted.Write());
 byte[] Bytes(XElement n)=>System.Text.Encoding.UTF8.GetBytes(n.ToString(SaveOptions.DisableFormatting));
 Check(ActualDebitPayloadAdmission.Read(Bytes(envelope),identity,17,operation,out _),"actual pure debit envelope admission");Check(ActualDebitPayloadAdmission.Read(Bytes(envelope),identity,17,operation,out _),"duplicate detached parse has no publication authority");
 Check(!ActualDebitPayloadAdmission.Read(Bytes(envelope),identity,18,operation,out _),"different actor refuses");Check(!ActualDebitPayloadAdmission.Read(Bytes(envelope),new RebirthStablePlayerIdentity{StorageKey="owner-B",CanonicalId=identity.CanonicalId},17,operation,out _),"different owner refuses");Check(!ActualDebitPayloadAdmission.Read(Bytes(envelope),identity,17,Guid.NewGuid(),out _),"different operation refuses");
 var malformed=new XElement(envelope);malformed.Name="camperNativePlayerDebit";Check(!ActualDebitPayloadAdmission.Read(Bytes(malformed),identity,17,operation,out _),"native root cannot enter Survivor parser");malformed=new XElement(envelope);malformed.Add(new XElement("extra"));Check(!ActualDebitPayloadAdmission.Read(Bytes(malformed),identity,17,operation,out _),"malformed envelope refuses");malformed=new XElement(envelope);malformed.Element("stationAdmission").ReplaceWith(prepared.Write());Check(!ActualDebitPayloadAdmission.Read(Bytes(malformed),identity,17,operation,out _),"unattempted12 cannot authorize debit");
 Console.WriteLine("PASS "+checks+" current-source actor image/phase/directional claims checks; native codec, disk witness and network lifecycle not qualified.");}
}
